def crumbs(f,name):
    ld=json.dumps({"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":SITE+"/"},{"@type":"ListItem","position":2,"name":name,"item":f"{SITE}/{f}"}]})
    return f'<nav class="crumbs" aria-label="Breadcrumb"><ol><li><a href="index.html">Home</a></li><li aria-current="page">{name}</li></ol></nav>',f'<script type="application/ld+json">{ld}</script>'
def inner(f,name,title,desc,h1,lead,body,img=None):
    c,ld=crumbs(f,name)
    kw={'img':img} if img else {}
    return head(title,desc,f,ld,**kw)+header(f)+f'<section class="page-hero"><div class="wrap">{c}<h1>{h1}</h1><p class="lead">{lead}</p></div></section>'+body+footer()
def write(f,s): open(f,'w',encoding='utf-8').write(s)
def sec(inner_html,cls=''): return f'<section class="sec {cls}"><div class="wrap">{inner_html}</div></section>'
def cta(h='Be part of what comes next',p='Volunteer, mentor, partner or simply join the community. Tell us how you would like to take part.'):
    return f'<section class="sec dark"><div class="wrap"><h2>{h}</h2><p>{p}</p><div class="row"><a class="btn" href="get-involved.html">Get Involved</a><a class="btn ghost" href="contact.html">Contact Us</a></div></div></section>'
def form(fid,opts,endpoint=''):
    o=''.join(f'<option value="{v}">{t}</option>' for v,t in opts)
    fld=lambda n,l,tag,extra='',opt='':f'<div><label for="{fid}-{n}">{l}{opt}</label>{tag.format(id=fid+"-"+n,n=n,extra=extra)}<div class="err" id="{fid}-{n}-err" aria-live="polite"></div></div>'
    return f'''<form data-form data-endpoint="{endpoint}" novalidate id="{fid}"><!-- Set data-endpoint to your form service URL (see README) -->
{fld("name","Full name",'<input id="{id}" name="{n}" autocomplete="name" required aria-describedby="{id}-err">')}
{fld("email","Email address",'<input id="{id}" name="{n}" type="email" autocomplete="email" required aria-describedby="{id}-err">')}
{fld("phone","Phone number",'<input id="{id}" name="{n}" type="tel" autocomplete="tel" aria-describedby="{id}-err">',opt=' <span class="opt">(optional)</span>')}
{fld("interest","Area of interest",'<select id="{id}" name="{n}" required aria-describedby="{id}-err"><option value="">Choose one</option>'+o+'</select>')}
{fld("message","Message",'<textarea id="{id}" name="{n}" required aria-describedby="{id}-err"></textarea>')}
<input class="hp" name="website" tabindex="-1" autocomplete="off" aria-hidden="true"><button class="btn" type="submit">Send message</button><div class="status" role="status" aria-live="polite"></div></form>'''
